# test exact fixed XOR of any neighborhood offsets from radius <=1
import itertools
for offsets in [[(dr,dc) for dr in range(-1,2) for dc in range(-1,2)],[(0,0),(0,-1),(0,1),(-1,0),(1,0)]]:
 matches=[]
 for mask in range(1<<len(offsets)):
  ok=True
  for A,B in zip(Ib,Ob):
   for r in range(6):
    for c in range(5):
     v=0
     for k,(dr,dc) in enumerate(offsets):
      rr,cc=r+dr,c+dc
      if mask>>k&1 and 0<=rr<6 and 0<=cc<5: v^=A[rr][cc]
     if v!=B[r][c]:ok=False;break
    if not ok:break
   if not ok:break
  if ok:matches.append(mask)
 print(len(offsets),matches[:5])

